def listwise_loss(scores: torch.Tensor, gold: torch.Tensor) -> torch.Tensor:
    logp = torch.log_softmax(scores, dim=-1)
    has = gold.any(dim=-1)
    if not has.any():
        return scores.sum() * 0.0
    return -(torch.logsumexp(logp.masked_fill(~gold, float("-inf"))[has], dim=-1)).mean()

